using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedLabel { get; set; } = string.Empty;

    [ColumnName("Score")]
    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public class TicketRequest
{
    public string Subject { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Priority { get; set; }
}

namespace TicketClassifier.Models;

public class TicketPredictionResponse
{
    public string Category { get; set; } = string.Empty;
    public float Confidence { get; set; }
    public Dictionary<string, float> Scores { get; set; } = new();
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainerService : IHostedService
{
    private readonly ILogger<ModelTrainerService> _logger;
    private readonly IWebHostEnvironment _env;

    public ModelTrainerService(ILogger<ModelTrainerService> logger, IWebHostEnvironment env)
    {
        _logger = logger;
        _env = env;
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        var mlContext = new MLContext(seed: 42);

        var dataPath = Path.Combine(_env.ContentRootPath, "Data", "tickets.csv");
        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _logger.LogInformation("Training model...");
        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        _logger.LogInformation("Micro Accuracy: {MicroAccuracy:F4}", metrics.MicroAccuracy);
        _logger.LogInformation("Macro Accuracy: {MacroAccuracy:F4}", metrics.MacroAccuracy);
        _logger.LogInformation("Log Loss: {LogLoss:F4}", metrics.LogLoss);

        var modelPath = Path.Combine(_env.ContentRootPath, "Data", "model.zip");
        mlContext.Model.Save(model, data.Schema, modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", modelPath);

        return Task.CompletedTask;
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/tickets")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;

    public TicketController(PredictionEnginePool<TicketData, TicketPrediction> predictionEnginePool)
    {
        _predictionEnginePool = predictionEnginePool;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = (float)request.Priority
        };

        var prediction = _predictionEnginePool.Predict(input);

        // Get category names from the model schema
        var labelNames = GetLabelNames();
        var scores = new Dictionary<string, float>();
        if (labelNames.Length > 0 && prediction.Score.Length == labelNames.Length)
        {
            for (int i = 0; i < labelNames.Length; i++)
            {
                scores[labelNames[i]] = prediction.Score[i];
            }
        }

        var confidence = prediction.Score.Length > 0 ? prediction.Score.Max() : 0f;

        return Ok(new TicketPredictionResponse
        {
            Category = prediction.PredictedLabel,
            Confidence = confidence,
            Scores = scores
        });
    }

    private string[] GetLabelNames()
    {
        var predEngine = _predictionEnginePool.GetPredictionEngine();
        try
        {
            var schema = predEngine.OutputSchema;
            var labelColumn = schema.GetColumnOrNull("Score");
            if (labelColumn == null) return [];

            var slotNames = new VBuffer<ReadOnlyMemory<char>>();
            labelColumn.Value.GetSlotNames(ref slotNames);
            return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
        }
        finally
        {
            _predictionEnginePool.ReturnPredictionEngine(predEngine);
        }
    }
}

