using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/tickets")]
public class TicketController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;

    public TicketController(PredictionEnginePool<TicketData, TicketPrediction> predictionEnginePool)
    {
        _predictionEnginePool = predictionEnginePool;
    }

    [HttpPost("classify")]
    public ActionResult<TicketPredictionResponse> Classify([FromBody] TicketRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = (float)request.Priority
        };

        var prediction = _predictionEnginePool.Predict(input);

        // Get category names from the model schema
        var labelNames = GetLabelNames();
        var scores = new Dictionary<string, float>();
        if (labelNames.Length > 0 && prediction.Score.Length == labelNames.Length)
        {
            for (int i = 0; i < labelNames.Length; i++)
            {
                scores[labelNames[i]] = prediction.Score[i];
            }
        }

        var confidence = prediction.Score.Length > 0 ? prediction.Score.Max() : 0f;

        return Ok(new TicketPredictionResponse
        {
            Category = prediction.PredictedLabel,
            Confidence = confidence,
            Scores = scores
        });
    }

    private string[] GetLabelNames()
    {
        var predEngine = _predictionEnginePool.GetPredictionEngine();
        try
        {
            var schema = predEngine.OutputSchema;
            var labelColumn = schema.GetColumnOrNull("Score");
            if (labelColumn == null) return [];

            var slotNames = new VBuffer<ReadOnlyMemory<char>>();
            labelColumn.Value.GetSlotNames(ref slotNames);
            return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
        }
        finally
        {
            _predictionEnginePool.ReturnPredictionEngine(predEngine);
        }
    }
}

